import './DataTable.css';

export interface Row {
  id: string;
  [key: string]: string;
}

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const PLACEHOLDER_ROW_COUNT = 5;
const PLACEHOLDER_CELL_COUNT = 3;

function deriveColumns(rows: Row[]): string[] {
  if (rows.length === 0) return [];
  return Object.keys(rows[0]).filter((k) => k !== 'id');
}

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  if (loading) {
    return (
      <table className="data-table">
        <tbody>
          {Array.from({ length: PLACEHOLDER_ROW_COUNT }).map((_, rowIndex) => (
            <tr key={rowIndex} className="data-table-row data-table-row--placeholder">
              {Array.from({ length: PLACEHOLDER_CELL_COUNT }).map((_, cellIndex) => (
                <td key={cellIndex} className="data-table-cell data-table-cell--shimmer">
                  <span className="data-table-shimmer-bar" />
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    );
  }

  const columns = deriveColumns(rows);

  return (
    <table className="data-table">
      {columns.length > 0 && (
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={col} className="data-table-header">
                {col}
              </th>
            ))}
          </tr>
        </thead>
      )}
      <tbody>
        {rows.map((row) => (
          <tr key={row.id} className="data-table-row">
            {columns.map((col) => (
              <td key={col} className="data-table-cell">
                {row[col]}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

