import './ChipBar.css';

interface ChipBarProps {
  statuses: string[];
  selected: Set<string>;
  onSelectionChange: (next: Set<string>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleClick(status: string): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <div className="chip-bar" role="group">
      {statuses.map((status) => (
        <button
          key={status}
          className="chip"
          aria-pressed={selected.has(status)}
          onClick={() => handleClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}

